function normalize(text) {
  var normalized = text.normalize('NFKC');
  var result = '';
  var inWhitespace = false;
  for (var i = 0; i < normalized.length; i++) {
    var ch = normalized[i];
    if (isWhitespace(ch)) {
      if (!inWhitespace) {
        if (result.length > 0) {
          result += ' ';
        }
        inWhitespace = true;
      }
    } else {
      result += ch;
      inWhitespace = false;
    }
  }
  return result;
}

function isWhitespace(ch) {
  return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\v' || ch === '\f' ||
